        if (StaticMeshComponent && StaticMeshComponent->GetMaterial(0))
        {
            UMaterialInterface* Material = StaticMeshComponent->GetMaterial(0);
            if (!Batches.Contains(Material))
            {
                Batches.Add(Material, TArray<AActor*>());
            }
            Batches[Material].Add(Actor);
        }
    }

    // Render each batch
    for (auto& Batch : Batches)
    {
        UMaterialInterface* Material = Batch.Key;
        TArray<AActor*>& ActorsInBatch = Batch.Value;

        // Profile material setup
        SCOPE_CYCLE_COUNTER(MaterialSetup);
        SetMaterial(Material);

        // Profile drawing objects
        SCOPE_CYCLE_COUNTER(DrawObjects);
        for (AActor* Actor : ActorsInBatch)
        {
            UStaticMeshComponent* StaticMeshComponent = Cast<UStaticMeshComponent>(Actor->GetRootComponent());
            if (StaticMeshComponent)
            {
                DrawMesh(StaticMeshComponent);
            }
        }
    }
}

void SetMaterial(UMaterialInterface* Material)
{
    // Set up the material on the GPU
    // This function should handle setting up the material
}

void DrawMesh(UStaticMeshComponent* MeshComponent)
{
    // Draw the mesh with the current material
    // This function should handle drawing the mesh
}
```

### Explanation

1. **Custom Profiling Scopes**:
   - Use `SCOPE_CYCLE_COUNTER` to measure the performance of specific sections of your code.
   - `RenderingPipeline`, `MaterialSetup`, and `DrawObjects` are custom counters that will help you identify bottlenecks.

2. **Group Objects by Material**:
   - Group objects by their materials to reduce the number of draw calls.

3. **Set Up Material and Draw Mesh**:
   - Measure the time taken to set up the material and draw the mesh.

### Using Built-In Profiling Tools

1. **Show Frame Stats**:
   - In the Unreal Editor, go to `Window > Developer Tools > Show Frame Stats` to enable real-time performance statistics.

2. **Shader Profiler**:
   - Go to `Window > Developer Tools > Shader Profiler` to analyze shader performance.
   - Identify expensive shaders and optimize them.

3. **Stat Commands**:
   - Use console commands like `stat fps`, `stat unit`, and `stat drawcalls` to gather detailed performance data.

### Analyzing Results

- **Identify Bottlenecks**: Use the profiling data to identify which parts of your rendering pipeline are taking the most time.
- **Optimize Shaders and Materials**: Simplify complex shaders and materials.
- **Batch Draw Calls**: Group objects by material to reduce the number of draw calls.

