         for (size_t i = 0; i < node->actors.size(); ++i) {
             for (size_t j = i + 1; j < node->actors.size(); ++j) {
                 PxActor* actorA = node->actors[i];
                 PxActor* actorB = node->actors[j];

                 // Perform collision check between actorA and actorB
