#include "PxPhysicsAPI.h"
#include <vector>

class PhysicsEngine {
public:
    void updateAgents(int numAgents) {
        std::vector<PxRigidDynamic*> rigidDynamics;
        rigidDynamics.reserve(numAgents);

        // Collect all rigid dynamics
        for (int i = 0; i < numAgents; i++) {
            rigidDynamics.push_back(agents[i].getRigidDynamic());
        }

        // Apply forces in a batch
